import { motion } from "framer-motion";
import { convertToFormField } from "../form-block.functions";
import { FormBlockFormElement } from "../form-block.types";
import { FormField, HandleFieldOnChangeFunc, useForm } from "@/core/helpers/form-builder";
import styles from "./form.module.less";
import { SecondaryButton } from "@/core/components/primitives/parks-button/parks-button";
import CalendarDateField from "@/core/components/primitives/calendar-date-field/calendar-date-field";
import InputError from "@/core/components/primitives/input-error/input-error";
import InputField from "@/core/components/primitives/input-field/input-field";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import SelectBox from "@/core/components/primitives/select-box/select-box";
import TextArea from "@/core/components/primitives/text-area/text-area";
import { useTranslation } from "react-i18next";
import { ExistingThemes } from "@/core/types";
import CheckboxButtons from "@/core/components/primitives/checkbox-buttons/checkbox-buttons";
import RichText, { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { formatToSekWithPossiblePrecision, multipleClassNames } from "@/core/helpers";
import { calculateEventualPrice } from "../form-block.functions";
import { MouseEventHandler, Ref, useId } from "react";

type Props = {
  title?: string;
  descriptionMarkdown?: {
    childMarkdownRemark: {
      html: string;
    };
  };
  /**
   * @deprecated Use descriptionMarkdown instead
   */
  description?: string;
  labelSendButton: string;
  labelMailHasBeenSentButton: string;
  formCompleted?: string;
  formCompletedNew?: RichTextType;
  isSendingEmail: boolean;
  mailHasBeenSent: boolean;
  formElements: Array<FormBlockFormElement>;
  onSubmit: (formFields: Map<string, FormField>) => void;
  componentTheme?: ExistingThemes;
};

export const Form = ({
  title,
  descriptionMarkdown,
  description,
  labelSendButton,
  labelMailHasBeenSentButton,
  formCompleted,
  formCompletedNew,
  isSendingEmail,
  mailHasBeenSent,
  formElements,
  onSubmit,
  componentTheme,
}: Props) => {
  const formId = useId();

  const isSending = isSendingEmail;
  const isSent = mailHasBeenSent;

  const { t } = useTranslation();
  const pickAlternativeLabel = t("selectBoxPickAlternative");

  const formFields: Map<string, FormField> = formElements.reduce((formFields, formElement) => {
    const formField = convertToFormField(formElement, pickAlternativeLabel);
    if (formField) formFields.set(formElement.internalTitle, formField);

    return formFields;
  }, new Map<string, FormField>());

  const initialForm = {
    fields: formFields,
  };

  const [form, isFormValid, handleFieldOnChange, , , getFormValidation, focusOn] = useForm(initialForm, true);

  const { totalPrice, hasAnyPricedElement } = calculateEventualPrice(form);

  const validateBeforeSubmit = () => {
    const { form: validatedForm, formValidationError } = getFormValidation();
    if (formValidationError || !isFormValid) {
      // getFormValidation() schedules the re-render that renders the error messages. Defer the focus
      // until after it commits, so the focused field's error is already in the DOM (and, for the date
      // field, folded into its accessible name) when the screen reader announces the field.
      requestAnimationFrame(() => focusOn("FIRST_INVALID"));
      return;
    }
    onSubmit(validatedForm.fields);
  };

  // Prevent form submission when mandatory fields doesnt meet criteria
  const handleSubmit: MouseEventHandler<HTMLButtonElement> = (e) => {
    e.preventDefault();
    validateBeforeSubmit();
  };

  return (
    <>
      {isSent && (
        <motion.div
          key="isSent"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.6 }}
          className={styles.formIsSentOverlay}
        >
          {formCompletedNew ? (
            <div className={styles.formIsSentWrapper}>
              <RichText richText={formCompletedNew} />
            </div>
          ) : (
            <div className={styles.formIsSentWrapper}>
              <h4>{formCompleted}</h4>
            </div>
          )}
        </motion.div>
      )}
      <form className={multipleClassNames(isSent && styles.formIsSent, styles.formWrapper, componentTheme)}>
        <h2 className={styles.title}>{title}</h2>
        {descriptionMarkdown && (
          <div
            className={multipleClassNames(styles.description, "link-with-icon")}
            dangerouslySetInnerHTML={{ __html: descriptionMarkdown.childMarkdownRemark.html }}
          ></div>
        )}
        <p className={styles.description}>{description}</p>

        {[...form.fields.values()].map((formField) => {
          return renderFormField(formId, formField, handleFieldOnChange, isSending || isSent);
        })}

        {hasAnyPricedElement && (
          <div className={styles.totalPrice}>
            <h4>
              {t("total")}: {formatToSekWithPossiblePrecision(totalPrice)}
            </h4>
          </div>
        )}

        {/* SecondaryButton since the background is primary color */}
        <SecondaryButton
          label={isSending ? labelMailHasBeenSentButton : labelSendButton}
          isFullWidth
          isDisabled={isSending}
          onClick={handleSubmit}
          className={styles.submitButton}
        />
      </form>
    </>
  );
};

const renderFormField = (
  formId: string,
  formField: FormField,
  handleFieldOnChange: HandleFieldOnChangeFunc,
  isDisabled: boolean,
) => {
  switch (formField.type) {
    case "INPUT_FIELD":
      return (
        <InputField
          key={formField.name}
          formField={formField}
          onChange={handleFieldOnChange}
          isDisabled={isDisabled}
          isRequired={formField.isRequired}
        />
      );

    case "TEXT_AREA":
      return (
        <div className={styles.formFieldWrapper} key={formField.name}>
          <TextArea onChange={handleFieldOnChange} formField={formField} isDisabled={isDisabled} />
        </div>
      );

    case "SELECT_BOX":
      return (
        <div className={styles.formFieldWrapper} key={formField.name}>
          <SelectBox onChange={handleFieldOnChange} formField={formField} isDisabled={isDisabled} />
        </div>
      );

    case "DATE_FIELD": {
      if (!formField.selectableCalendarDates) return null;

      const dateLabelId = `${formId}-${formField.name}-label`;
      const dateErrorId = `${formId}-${formField.name}-error`;
      const dateHasError = formField.isValid === false;
      // The calendar renders react-day-picker's grid of day buttons, but focusing a single calendar day
      // would announce that date, not the field-level error, so the wrapper is a focusable group (tabIndex={-1})
      // with the error in aria-labelledby, which screen readers announce.
      const dateLabelledBy =
        [formField.label ? dateLabelId : null, dateHasError ? dateErrorId : null].filter(Boolean).join(" ") ||
        undefined;

      return (
        <div
          className={styles.formFieldWrapper}
          key={formField.name}
          ref={formField.inputRef as Ref<HTMLDivElement>}
          tabIndex={-1}
          role="group"
          aria-labelledby={dateLabelledBy}
          aria-invalid={dateHasError}
        >
          {formField.label && (
            <InputLabel
              id={dateLabelId}
              label={formField.label}
              inputName={formField.name}
              isRequired={formField.isRequired}
            />
          )}
          <CalendarDateField
            calendarDates={formField.selectableCalendarDates}
            fullyBookedDates={formField.fullyBookedDates}
            onChangeDate={(date: Date) => {
              handleFieldOnChange(formField.name, date.toISOString());
            }}
            removeDaysInThePast={formField.removeDaysInThePast ?? false}
          />
          <div id={dateErrorId}>
            <InputError
              showError={dateHasError}
              isRequired={formField.isRequired}
              errorText={formField.errorText}
              validationType={formField.validationType}
            />
          </div>
        </div>
      );
    }

    case "CHECK_BOX":
      if (formField.checkBoxOptions) {
        return (
          <div className={styles.formFieldWrapper} key={formField.name}>
            {formField.label && (
              <InputLabel label={formField.label} inputName={formField.name} isRequired={formField.isRequired} />
            )}
            <CheckboxButtons
              key={formField.name}
              formField={formField}
              options={formField.checkBoxOptions}
              onChange={handleFieldOnChange}
              name={formField.name}
              isDisabled={isDisabled}
              value={formField.value}
              checkboxClassName={styles.checkboxItems}
            />
            <InputError
              showError={formField.isValid === false}
              isRequired={formField.isRequired}
              errorText={formField.errorText}
            />
          </div>
        );
      }
      return null;

    case "AMOUNT_FIELD":
      return (
        <InputField
          key={formField.name}
          formField={formField}
          type="number"
          min={formField.minValue ?? 0}
          max={formField.maxValue}
          onChange={(fieldName, fieldValue) => handleFieldOnChange(fieldName, fieldValue, { instantValidate: true })}
          isDisabled={isDisabled}
          isRequired={formField.isRequired}
        />
      );

    default:
      console.error("MISSING FORM FIELD TYPE: " + formField.type);
      return null;
  }
};
