import { DateHelper, exhaustiveCheck } from "@/core/helpers";
import { FormBlockFormElement, ServiceDataField } from "./form-block.types";
import { FormField, buildField } from "@/core/helpers/form-builder";

export const convertToFormField = (
  formElement: FormBlockFormElement,
  pickAlternativeLabel: string,
): FormField | undefined => {
  switch (formElement.type) {
    case "textField": {
      return buildField(formElement.internalTitle, {
        type: "INPUT_FIELD",
        label: formElement.label,
        errorText: formElement.errorText,
        isRequired: formElement.isRequired || false,
      });
    }
    case "textArea": {
      return buildField(formElement.internalTitle, {
        type: "TEXT_AREA",
        label: formElement.label,
        errorText: formElement.errorText,
        isRequired: formElement.isRequired || false,
      });
    }
    case "select": {
      return buildField(formElement.internalTitle, {
        type: "SELECT_BOX",
        label: formElement.label,
        isRequired: formElement.isRequired || false,
        errorText: formElement.errorText,
        selectBoxOptions: formElement.listValues?.list.map((option) => ({
          label: option.value,
          value: option.key,
        })),
        placeholder: pickAlternativeLabel,
      });
    }
    case "singleDateSelection": {
      return buildField(formElement.internalTitle, {
        type: "DATE_FIELD",
        label: formElement.label,
        isRequired: formElement.isRequired || false,
        validationType: "DATE",
        errorText: formElement.errorText,
        selectableCalendarDates: formElement.calendarDates,
        fullyBookedDates: formElement.fullyBookedDates,
        removeDaysInThePast: formElement.removeDaysInThePast,
      });
    }
    case "emailField": {
      return buildField(formElement.internalTitle, {
        type: "INPUT_FIELD",
        label: formElement.label,
        inputMode: "email",
        validationType: "EMAIL",
        errorText: formElement.errorText,
        isRequired: true,
      });
    }
    case "checkbox": {
      return buildField(formElement.internalTitle, {
        type: "CHECK_BOX",
        label: formElement.label,
        isRequired: formElement.isRequired || false,
        checkBoxOptions: formElement.listValues?.list.map((option) => ({
          label: option.value,
          value: option.key,
        })),
        errorText: formElement.errorText,
        price: formElement.price,
        priceType: formElement.priceType,
      });
    }
    case "amount": {
      return buildField(formElement.internalTitle, {
        type: "AMOUNT_FIELD",
        label: formElement.label,
        isRequired: formElement.isRequired,
        errorText: formElement.errorText,
        price: formElement.price,
        minValue: formElement.minValue,
        maxValue: formElement.maxValue,
        baseAmount: formElement.baseAmount,
      });
    }
    case "phoneNumber": {
      return buildField(formElement.internalTitle, {
        type: "INPUT_FIELD",
        label: formElement.label,
        inputMode: "tel",
        validationType: "PHONE",
        errorText: formElement.errorText,
        isRequired: formElement.isRequired || false,
      });
    }

    default: {
      console.error("MISSING FORM FIELD TYPE: " + formElement.type);
      return undefined;
    }
  }
};

export const UNANSWERED_VALUE = " - ";

const getValueOfFormField = (formField: FormField): string => {
  if (formField.type === undefined) {
    return UNANSWERED_VALUE;
  }
  switch (formField.type) {
    case "INPUT_FIELD": {
      return formField.value || UNANSWERED_VALUE;
    }
    case "TEXT_AREA": {
      return formField.value || UNANSWERED_VALUE;
    }
    case "SELECT_BOX": {
      return formField.value ?? UNANSWERED_VALUE;
    }
    case "DATE_FIELD": {
      return formField.value ? DateHelper.toStringYYYYMMDD(formField.value) : UNANSWERED_VALUE;
    }
    case "IMAGE_FIELD": {
      return UNANSWERED_VALUE;
    }
    case "CHECK_BOX": {
      return formField.value ?? UNANSWERED_VALUE;
    }
    case "AMOUNT_FIELD": {
      return formField.value || UNANSWERED_VALUE;
    }
    default: {
      return exhaustiveCheck(formField.type);
    }
  }
};

export const COULD_NOT_FIND_FORM_ELEMENT_EMAIL_LABEL = "KUNDE EJ HITTA URSPRUNGSFRÅGA";
export const SHOWN_TOTAL_PRICE_LABEL = "Visat totalpris";

export const convertFormToServiceData = (
  formFields: Map<string, FormField>,
  formElements: Array<FormBlockFormElement>,
): Array<ServiceDataField> => {
  const toReturn = [...formFields.keys()].map((key) => {
    const formField = formFields.get(key) as FormField; //This is safe because we know the key exists
    const originalFormElement = formElements.find((formElement) => formElement.internalTitle === formField.name);
    if (originalFormElement === undefined) {
      return {
        label: COULD_NOT_FIND_FORM_ELEMENT_EMAIL_LABEL,
        value: getValueOfFormField(formField),
      };
    }
    return {
      label: originalFormElement.emailLabel,
      value: getValueOfFormField(formField),
    };
  });

  const { hasAnyPricedElement, totalPrice } = calculateEventualPrice({ fields: formFields });

  if (hasAnyPricedElement) {
    toReturn.push({
      label: SHOWN_TOTAL_PRICE_LABEL,
      value: `${totalPrice} kr`,
    });
  }

  return toReturn;
};

function isPricedField(field: FormField): field is FormField & { price: number } {
  return typeof field.price === "number" && field.price > 0;
}

export const calculateEventualPrice = (form: {
  fields: Map<string, FormField>;
}): { hasAnyPricedElement: boolean; totalPrice: number } => {
  const allFields = [...form.fields.values()];
  const baseAmountField = allFields.find((f) => f.type === "AMOUNT_FIELD" && f.baseAmount === true);
  const baseAmountValue = Number(baseAmountField?.value || 0);
  const pricedFields = allFields.filter(isPricedField);
  if (pricedFields.length === 0) {
    return { hasAnyPricedElement: false, totalPrice: 0 };
  }
  const total = pricedFields.reduce((acc, field) => {
    const price = field.price;
    if (field.type === "AMOUNT_FIELD") {
      const units = Number(field.value || 0);
      return acc + units * price;
    }
    if (field.type === "CHECK_BOX") {
      const selected = field.value ? field.value.split(", ") : [];
      if (selected.length === 0) {
        return acc;
      }
      if (field.priceType === "pricePerUnit") {
        return acc + selected.length * price * baseAmountValue;
      } else {
        return acc + price;
      }
    }
    return acc;
  }, 0);
  return { hasAnyPricedElement: true, totalPrice: total };
};
