import { ComponentProps, RefObject, forwardRef } from "react";
import styles from "./text-area.module.less";
import { FormField, assignToRefs } from "@/core/helpers/form-builder";
import { multipleClassNames } from "@/core/helpers";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import InputHelperText from "@/core/components/primitives/input-helper-text/input-helper-text";
import InputError from "@/core/components/primitives/input-error/input-error";
import { HTMLMotionProps, motion } from "framer-motion";

type Props = Omit<ComponentProps<"textarea">, "onChange" | "className"> & {
  label?: string;
  helperText?: string;
  focus?: boolean;
  error?: string;
  isValid?: boolean;
  isDisabled?: boolean;
  isRequired?: boolean;
  inputClassName?: string;
  formField?: FormField;
  onChange: (name: string, value: string) => void;
  resizable?: boolean;
  isEditable?: boolean;
  className?: string;
  inputRef?: RefObject<HTMLTextAreaElement>;
} & Omit<HTMLMotionProps<"textarea">, "onChange">;

const TextArea = forwardRef<HTMLTextAreaElement, Props>(
  (
    {
      name,
      value,
      formField,
      isValid,
      error,
      isEditable,
      isDisabled,
      label,
      placeholder,
      helperText,
      resizable,
      isRequired,
      className,
      onBlur: propsOnBlur,
      onKeyUp: propsOnKeyUp,
      onKeyDown: propsOnKeyDown,
      focus,
      inputClassName,
      inputRef,
      onChange,
      ...rest
    }: Props,
    ref,
  ) => {
    if (formField) {
      name = name ? name : formField.name;
      value = value ? value : formField.value;
      isValid = typeof isValid === "boolean" ? isValid : formField.isValid ?? undefined;
      error = error ? error : formField.errorText;
      isEditable = typeof isEditable === "boolean" ? isEditable : formField.isEditable;
      label = label ? label : formField.label;
      isRequired = isRequired ? isRequired : formField.isRequired;
      placeholder = placeholder ? placeholder : formField.placeholder;
    }

    if (isEditable === false || (formField && formField.isEditable === false)) {
      isDisabled = true;
    }

    const displayError = isValid === false;
    const errorId = name ? `${name}-error` : undefined;

    const onBlur = (event: React.FocusEvent<HTMLTextAreaElement>) => {
      if (propsOnBlur && typeof propsOnBlur === "function") {
        propsOnBlur(event);
      }
    };

    /** Native input onKeyUp */
    const onKeyUp = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (propsOnKeyUp && typeof propsOnKeyUp === "function") {
        propsOnKeyUp(event);
      }
    };

    /** Native input onKeyDown */
    const onKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (propsOnKeyDown && typeof propsOnKeyDown === "function") {
        propsOnKeyDown(event);
      }
    };

    return (
      <div className={multipleClassNames(styles.wrapper, className)}>
        <div className={styles.innerWrapper}>
          {label && <InputLabel label={label} inputName={name} isRequired={isRequired} />}
          <motion.textarea
            id={name ? name : undefined}
            ref={(e) => assignToRefs(e, inputRef, formField?.inputRef)}
            tabIndex={0}
            className={multipleClassNames(styles.input, inputClassName, displayError && styles.inputError)}
            data-is-resizable={resizable}
            value={value ? value : ""}
            name={name ? name : undefined}
            disabled={isDisabled}
            autoFocus={focus}
            placeholder={placeholder}
            aria-invalid={displayError || undefined}
            aria-describedby={displayError && errorId ? errorId : undefined}
            onChange={(event) => onChange(event.target.name, event.target.value)}
            onBlur={onBlur}
            onKeyUp={onKeyUp}
            onKeyDown={onKeyDown}
            {...rest}
          />
          {helperText && <InputHelperText helperText={helperText} />}
          <InputError id={errorId} showError={displayError} isRequired={isRequired} errorText={error} />
        </div>
      </div>
    );
  },
);

TextArea.displayName = "TextArea";

export default TextArea;
